module lights_max (\n    input clk,\n    input rst_n,\n    input start,\n    input [7:0] initial_state,\n    input [2:0] a [0:7],\n    input [2:0] b [0:7],\n    output reg [7:0] max_count\n);\n\n    // State definitions\n    localparam [2:0] IDLE      = 3'b000;\n    localparam [2:0] SIMULATE  = 3'b001;\n    localparam [2:0] UPDATE_MAX= 3'b010;\n    localparam [2:0] NEXT_TIME = 3'b011;\n    localparam [2:0] DONE      = 3'b100;\n\n    reg [2:0] state;\n    reg [6:0] time_counter;\n    reg [2:0] light_counter;\n    reg [7:0] current_states;\n    reg [7:0] max_count_reg;\n    reg [7:0] current_count;\n\n    wire [2:0] period = a[light_counter];\n    wire [2:0] offset = b[light_counter];\n    wire light_on = current_states[light_counter];\n    wire should_toggle = (time_counter >= offset) && \n                        ((time_counter - offset) % period == 0);\n\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= IDLE;\n            time_counter <= 7'd0;\n            light_counter <= 3'd0;\n            current_states <= 8'd0;\n            max_count_reg <= 8'd0;\n            current_count <= 8'd0;\n            max_count <= 8'd0;\n        end else begin\n            case (state)\n                IDLE: begin\n                    if (start) begin\n                        current_states <= initial_state;\n                        time_counter <= 7'd0;\n                        light_counter <= 3'd0;\n                        max_count_reg <= 8'd0;\n                        current_count <= initial_state[0] + initial_state[1]\n                                      + initial_state[2] + initial_state[3]\n                                      + initial_state[4] + initial_state[5]\n                                      + initial_state[6] + initial_state[7];\n                        state <= SIMULATE;\n                    end\n                end\n\n                SIMULATE: begin\n                    if (should_toggle) begin\n                        current_states[light_counter] <= ~light_on;\n                        if (light_on) current_count <= current_count - 8'd1;\n                        else current_count <= current_count + 8'd1;\n                    end\n\n                    if (light_counter == 3'd7) begin\n                        light_counter <= 3'd0;\n                        state <= UPDATE_MAX;\n                    end else begin\n                        light_counter <= light_counter + 3'd1;\n                    end\n                end\n\n                UPDATE_MAX: begin\n                    if (current_count > max_count_reg) max_count_reg <= current_count;\n                    state <= NEXT_TIME;\n                end\n\n                NEXT_TIME: begin\n                    if (time_counter == 7'd120) begin\n                        max_count <= max_count_reg;\n                        state <= DONE;\n                    end else begin\n                        time_counter <= time_counter + 7'd1;\n                        current_count <= current_states[0] + current_states[1]\n                                      + current_states[2] + current_states[3]\n                                      + current_states[4] + current_states[5]\n                                      + current_states[6] + current_states[7];\n                        state <= SIMULATE;\n                    end\n                end\n\n                DONE: begin\n                    state <= DONE;\n                end\n\n                default: state <= IDLE;\n            endcase\n        end\n    end\nendmodule